<script setup lang="ts">
import {onMounted,reactive,ref} from 'vue';import {ElMessage,ElMessageBox} from 'element-plus';import {cases,create,one,remove,statistics,update} from '@/api';import {useUser} from '@/stores/user';import {useRouter} from 'vue-router';
const u=useUser(),router=useRouter(),rows=ref<any[]>([]),total=ref(0),stats=ref<any>({status:{}}),busy=ref(false),dialog=ref(false),edit=ref<number|undefined>();const q=reactive<any>({current:1,size:10,module:'',priority:'',status:'',keyword:''});const f=reactive<any>({title:'',module:'',priority:'P1',status:'未执行',description:'',expected_result:''});
async function load(){busy.value=true;try{const d:any=await cases(q);rows.value=d.records;total.value=d.total}finally{busy.value=false}}async function stat(){stats.value=await statistics()}function search(){q.current=1;load()}function reset(){Object.assign(q,{current:1,module:'',priority:'',status:'',keyword:''});load()}function add(){edit.value=undefined;Object.assign(f,{title:'',module:'',priority:'P1',status:'未执行',description:'',expected_result:''});dialog.value=true}async function modify(r:any){const d:any=await one(r.id);edit.value=d.id;Object.assign(f,{...d,expected_result:d.expectedResult});dialog.value=true}async function save(){if(!f.title||!f.module)return ElMessage.warning('请填写标题和模块');if(edit.value)await update(edit.value,f);else await create(f);dialog.value=false;ElMessage.success('保存成功');await Promise.all([load(),stat()])}async function del(r:any){await ElMessageBox.confirm('确定删除「'+r.title+'」吗？','删除用例',{type:'warning'});await remove(r.id);await Promise.all([load(),stat()])}function logout(){u.logout();router.push('/login')}const tag=(x:string)=>({P0:'danger',P1:'warning',P2:'primary',P3:'info',通过:'success',失败:'danger',阻塞:'warning',未执行:'info'} as any)[x]||'info';onMounted(()=>Promise.all([u.load(),load(),stat()]));
</script>
<template><main class="work"><header><div><small>QA / CASE LIBRARY</small><h1>用例管理平台</h1></div><div>{{u.data?.nickname}} <el-button text @click="logout">退出登录</el-button></div></header><section class="stats"><article>用例总数<strong>{{stats.total||0}}</strong></article><article>通过<strong>{{stats.status['通过']||0}}</strong></article><article>失败<strong>{{stats.status['失败']||0}}</strong></article><article>未执行<strong>{{stats.status['未执行']||0}}</strong></article></section><section class="panel filters"><small>筛选用例</small><el-select v-model="q.module" clearable placeholder="所属模块"><el-option label="用户认证" value="用户认证"/><el-option label="用例管理" value="用例管理"/></el-select><el-select v-model="q.priority" clearable placeholder="优先级"><el-option v-for="x in ['P0','P1','P2','P3']" :label="x" :value="x"/></el-select><el-select v-model="q.status" clearable placeholder="状态"><el-option v-for="x in ['未执行','通过','失败','阻塞']" :label="x" :value="x"/></el-select><el-input v-model="q.keyword" placeholder="搜索标题或描述" @keyup.enter="search"/><el-button type="primary" @click="search">查询</el-button><el-button @click="reset">重置</el-button></section><section class="panel table"><div class="tablehead"><div><small>用例列表</small><br/>共 {{total}} 条记录</div><el-button type="primary" @click="add">新增用例</el-button></div><el-table :data="rows" v-loading="busy"><el-table-column prop="title" label="标题" min-width="200"/><el-table-column prop="module" label="模块" width="120"/><el-table-column prop="priority" label="优先级" width="90"><template #default="s"><el-tag :type="tag(s.row.priority)">{{s.row.priority}}</el-tag></template></el-table-column><el-table-column prop="status" label="状态" width="100"><template #default="s"><el-tag :type="tag(s.row.status)">{{s.row.status}}</el-tag></template></el-table-column><el-table-column prop="creator" label="创建人" width="100"/><el-table-column prop="createTime" label="创建时间" width="180"/><el-table-column label="操作" width="130"><template #default="s"><el-button link type="primary" @click="modify(s.row)">编辑</el-button><el-button link type="danger" @click="del(s.row)">删除</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="q.current" :page-size="q.size" :total="total" layout="total,prev,pager,next" @current-change="load"/></section><el-dialog v-model="dialog" :title="edit?'编辑用例':'新增用例'" width="600"><el-form label-width="85"><el-form-item label="用例标题"><el-input v-model="f.title"/></el-form-item><el-form-item label="所属模块"><el-input v-model="f.module"/></el-form-item><el-form-item label="优先级"><el-radio-group v-model="f.priority"><el-radio-button v-for="x in ['P0','P1','P2','P3']" :label="x"/></el-radio-group></el-form-item><el-form-item label="执行状态"><el-select v-model="f.status"><el-option v-for="x in ['未执行','通过','失败','阻塞']" :label="x" :value="x"/></el-select></el-form-item><el-form-item label="用例描述"><el-input v-model="f.description" type="textarea"/></el-form-item><el-form-item label="预期结果"><el-input v-model="f.expected_result" type="textarea"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存用例</el-button></template></el-dialog></main></template>
